-- GENERATED by `wfj generate` from data/gossip/gossip-57.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["57009b36d2617606"] = { "I Terrigeni sono una razza sintetica progettata dai Creatori, una delle razze seme della popolazione iniziale del mondo designato come Azeroth. I Terrigeni furono creati per aiutare i Creatori a plasmare le regioni profonde di questo mondo.\n\nSono una modifica della matrice standard degli esseri sotterranei usata su altri mondi seminati dai Creatori. La costruzione di questa razza prototipo ha generato varie anomalie, osservate dopo la sintesi iniziale.", "." },
  ["5702e95589dbbacd"] = { "Minaccia fisica rilevata! Manovra evasiva! COCCODÈ!", "." },
  ["5703f5c48586c9da"] = { "Ah, mi sa che sto correndo troppo. ⟦Ras Frostwhisper=Ras Soffiogelo⟧ è il sovrintendente di questa scuola, l'essere che si occupa dell'addestramento di tutti i suoi Maestri Oscuri. Luogotenente e allievo prediletto di Kel'Thuzad. Un tempo era un mago autodidatta di Stromgarde: un mago rinnegato che non aveva mai ricevuto una formazione regolare da Dalaran.\n\nQuando Kel'Thuzad fondò il Culto, Ras fu tra i primi a unirsi alle sue file. Ras sapeva che attraverso la magia oscura avrebbe trovato l'immortalità.", "." },
  ["5706a363fda0e81e"] = { "Devi fare i punti più piccoli, {name}. Ti cadranno meno oggetti dalle faretre e dalle sacche per munizioni. E poi, a nessuno piace una tunica bitorzoluta.", "." },
  ["57092f9267ff939d"] = { "Perché mai ti servirebbe un'abilità del genere? Solo la gente disonesta vorrebbe imparare a scassinare le serrature.\n\nSe proprio vuoi imparare, il posto migliore dove cercare è la Città Vecchia. Probabilmente in uno di quei vicoli secondari.", "." },
  ["571027f32f115883"] = { "Quanti insetti sporcaccioni da queste parti.", "." },
  ["571252ecdb613b8c"] = { "Cos'era? Un gigante marino? Meglio prevenire che curare. Fuoco!", "." },
  ["5712f6a8c5d6ebe2"] = { "Il ⟦Frostwolf Graveyard=Cimitero dei Lupi Bianchi⟧ è sotto attacco! Se nessuno interviene, l'⟦Alliance=Alleanza⟧ lo conquisterà!", "." },
  ["571504b8451e1221"] = { "D'accordo, capo. Ma è proprio quello che vuoi? Mi sembra solo uno spreco di un buon allenamento.", "." },
  ["571977d858ef4a8c"] = { "Hai già il distintivo, {name}?\n\nSarà uno strumento fondamentale per infiltrarci in quella che credo sia la più grande minaccia per l'⟦Horde=Orda⟧, e per trovare finalmente la pace nella nostra nuova casa.\n\nScoprirai quanto intricata possa essere la ragnatela che uomini e orchi sanno tessere quando li muovono l'avidità e il potere. I piani nascosti, la corruzione: tutto ti sarà chiaro. Ti ritroverai nel mezzo di una guerra di cui non hai mai sospettato l'esistenza.", "." },
  ["571a467ad5c75ff7"] = { "Hai l'aria di chi cerca avventure. Io ne avevo avute abbastanza quando noi troll siamo arrivati qui. Ora prendo ogni giorno come viene, e addestro altra gente ad affrontare le avventure al posto mio.", "." },
  ["571a66c077e088d7"] = { "C'è differenza tra melma e poltiglia?", "." },
  ["572c7c5bb738c35b"] = { "<Benvenuto/Benvenuta>, {name}! Ti interessa imparare la sartoria?", "." },
  ["573012a1e882c69b"] = { "Dov'è l'anziano Zoccolo Sanguinario?", "." },
  ["5733f7fb709d6d2a"] = { "Che le benedizioni della notte siano tue, <amico/amica>! Sono ⟦Illiyana Moonblaze=Illiyana Fiammaluna⟧, la principale fornitrice delle ⟦Silverwing Sentinels=Sentinelle Alargentea⟧ qui a ⟦Ashenvale=Valtetra⟧. Man mano che migliorerai la tua reputazione presso le ⟦Sentinels=Sentinelle⟧, ti metterò a disposizione una scelta di ottime merci da usare nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧. Se avessi bisogno di riparare l'equipaggiamento, offro anche quel servizio.", "." },
  ["5735e0c1ced87097"] = { "Per raggiungere ⟦The Crossroads=Crocevia⟧, {name}, segui la strada verso est e poi verso nord.", "." },
  ["5737444041ef74c5"] = { "Non ne posso più!", "." },
  ["573f16acce326976"] = { "MmmmmMmmmm... Enorme cracker chimicamente modificato....", "." },
  ["5743c82711299fcf"] = { "C'è sempre... il Brandicenere.", "." },
  ["57495169361bf91e"] = { "Premi il pulsante rosso con la scritta «E.C.A.C.».", "." },
  ["574b701e7f051936"] = { "Hai sentito cos'è successo a Ban'aethal? I Pacificatori avvertono la gente di stare lontana dalle rovine e da tutta la Shadowgale Forest.\r\n\nHo sentito qualcuno alla locanda parlare di malevoli spiriti del vento che sembravano poco più di una sagoma indistinta, come se fossero... svuotati, in qualche modo.\r\n\nMi vengono i brividi solo a pensarci.", "." },
  ["57519a901c6fb1ff"] = { "Un essere di grande potere si è risvegliato.", "." },
  ["57561b5ecb530a5f"] = { "Era destino, Windsor? Se sei venuto in cerca di morte, allora la profezia si è compiuta. Che la tua coscienza marcisca nella ⟦Twisting Nether=Distorsione Fatua⟧. Finite il resto di questi insetti impiccioni, figli miei. Bolvar, sei stato un burattino piacevole.", "." },
  ["575ce926b1a7e2a7"] = { "Ce l'abbiamo fatta, {name}!", "." },
  ["57705db0a34cb5f5"] = { "Non riesco proprio a immaginare perché qualcuno voglia rubare questi componenti a questo costrutto. A parte il gyrozephyr, non hanno quasi nessuna utilità pratica. E perfino il gyro sarebbe pressoché inutile fuori dallo scopo per cui è stato creato.", "." },
  ["577c0fab8faed76f"] = { "Se lo chiedi a me, Grif passa un po' troppo tempo con gli animali. Eppure nessun altro conosce la via del cacciatore come lui. Cercalo fuori dalla fucina di Kharanos.", "." },
  ["577c475f46dc95ae"] = { "... Un messaggio da Banehollow? Che messaggio? Ha bisogno del suo grande consigliere e servitore, Ulathek? Richiede la mia presenza?", "." },
  ["578114aaa1d35b59"] = { "Sono anni che non vedo un'armatura migliore, {name}. Da quando mi addestravo sotto ⟦Grumnus Steelshaper=Grumnus Plasmacciaio⟧ nella ⟦Great Forge=Grande Forgia⟧. Scommetto che potrebbe insegnarti cose sulla fabbricazione delle armature che ti interesserebbero.", "." },
  ["579335d90289f966"] = { "%s trabocca di ratti neri morti. Mmmm....", "." },
  ["5793c3f141a9a71f"] = { "Ci hanno mandato qui da Darnassus per aiutare i Piccatonante nel momento del bisogno.", "." },
  ["579745397e137aaf"] = { "Ah, ecco fatto. Ora Keever deve provare questa fiala e vedere se funziona.", "." },
  ["57979be6c2a7234d"] = { "Grazie, {name}.", "." },
  ["579c802a1998f212"] = { "%s si decompone in polvere.", "." },
  ["57a2e02b459956ab"] = { "Se scopri un modo per migliorare il congegno, fammelo sapere!", "." },
  ["57ad3b36a2e64b72"] = { "Cerca l'assoluzione, Eranikus. Tutto sarà perdonato...", "." },
  ["57b00b9eb596502c"] = { "Ehi, Pratt, puoi insegnarmi di nuovo a fare una ⟦Wild Leather Vest=Veste di Cuoio Selvatico⟧?", "." },
  ["57b4ce45306670de"] = { "%s crolla e comincia a fumare lentamente.", "." },
  ["57b8c2b6d8aace1b"] = { "Esigo che tutti i miei allievi dimostrino la loro dedizione. Ora tocca a te...", "." },
  ["57be0104c5bd8382"] = { "Aspetto il cristallo dell'oracolo, {class}. Trovare e distruggere questo sire Azrethoc ci farebbe guadagnare grande favore presso il Capoguerra, a entrambi. Faremmo bene a lavorare insieme, e in fretta, così da perseguire i nostri scopi e ingraziarci il Capoguerra.", "." },
  ["57c3ef93235dba72"] = { "Sembra il posto perfetto per un pisolino...", "." },
  ["57c69dd8c4984659"] = { "La mia mente. . .la mia carne. . .sto. . .marcendo. . . .!", "." },
  ["57cfe5ac3fbbb4c4"] = { "Vuoi imparare a lavorare con incudine e martello, eh? ⟦Karn Stonehoof=Karn Zoccolo Granitico⟧ può insegnartelo. Ha una fucina sull'altura inferiore, vicino allo stagno.", "." },
  ["57dadc6ab3ba5733"] = { "La mia conoscenza della storia degli elfi della notte è limitata, ma si dice che molto tempo fa, quando gli elfi della notte consideravano ancora sacra l'arte degli incantesimi arcani, Azshara fosse la più grande della loro stirpe. Una donna bellissima, che nominarono regina. Purtroppo, fu la sua dipendenza dall'arcano a diventare un giorno il catalizzatore degli eventi più devastanti della storia di questo mondo.", "." },
  ["57e27109658342e2"] = { "La terra è stata generosa con il nostro popolo, {class}. Dobbiamo essere grati per la nostra fortuna.", "." },
  ["57e3d2c02d95db15"] = { "Una volta ho sentito sussurrare che la storia dei satiri è in qualche modo legata a quella degli Elfi della Notte, ma i miei stimati ospiti si sono mostrati restii a parlarne.", "." },
  ["57e5a57291a8003b"] = { "<Bentornato/Bentornata>, {name}. Ti ho già detto quanto è bello avere qualcuno con cui parlare?\n\nBene allora, mettiamoci al lavoro. Qual è la prossima cosa da fare?", "." },
  ["57fda7a3bdf933a3"] = { "Il Dun Baldar South Bunker protegge i fianchi sud ed est di Dun Baldar.\n\nNon è controllato da nessuna delle due parti.", "." },
})
